  "ui.ef4345d208a1": "在内置浏览器中打开 URL",
  "ui.66550c977bd0": "打开一个内置浏览器标签页并返回其 tab_id 和 CDP 句柄。该标签页在其任务生命周期内受保护，不会被挂起，直到 browser.release_tab 声明所有运行中和队列中的浏览器工作已完成。",
  "ui.1953aea25d4a": "要打开的网站 URL。",
  "ui.b8252e00a373": "浏览器提供程序。使用 builtin 或 auto。",
  "ui.56ac5df8600f": "恢复浏览器标签页",
  "ui.0a7962e0bb15": "获取属于当前对话的标签页的全新受保护 CDP 句柄。挂起的标签页会重新加载其保存的 URL（而非之前的文档），保留 tab_id 但分配新的 target_id。活动标签页则保持其文档不变。始终使用返回的句柄。保护状态将持续到 browser.release_tab 为止。",
  "ui.04c1eacc6e57": "由 browser.open_url 或 browser.restore_tab 返回的逻辑 tab_id。",
  "ui.b25cdf5dde1a": "释放浏览器标签页",
  "ui.01fdfeffe6f7": "声明此对话标签页上所有正在运行和排队的浏览器工作已完成，并移除其挂起保护。Release 操作不会关闭、挂起或使当前目标失效。用户随后可以手动挂起它。在启动后续的浏览器工作之前，请调用 browser.restore_tab 并使用其返回的保护句柄。",
  "ui.699acf6eca27": "浏览器工作已完成的逻辑 tab_id。",
  "ui.5c4aee38f11b": "设置内置浏览器代理",
  "ui.9833d00fe878": "通过 HTTP/SOCKS 代理路由所有内置浏览器流量（例如，从其他位置浏览）。适用于每个内置浏览器标签页，直到被清除。传入空代理以恢复系统网络设置。",
  "ui.c2f3d7f28d82": "代理 URL，如 http://user:pass@host:8080 或 socks5://host:1080；使用环境变量 GET3W_BROWSER_PROXY_NAME 的 env:NAME 格式；或为空以清除。",
